<script setup lang="ts">
import {ref,watch} from 'vue'
import {Plus,X} from 'lucide-vue-next'
import type {EventParticipantInput} from '@nextspace/contracts'
import {normalizeEventAttendees} from '@nextspace/core/event-scheduling.mjs'
const props=defineProps<{modelValue:EventParticipantInput[];disabled?:boolean;organizer?:string;reason?:string}>()
const emit=defineEmits<{'update:modelValue':[value:EventParticipantInput[]];pending:[value:boolean]}>()
const email=ref(''),name=ref(''),error=ref('')
watch([email,name],()=>emit('pending',Boolean(email.value||name.value)),{immediate:true})
function add(){if(props.disabled)return;error.value='';try{const values=normalizeEventAttendees([...props.modelValue,{email:email.value,...(name.value.trim()?{name:name.value}:{})}]);emit('update:modelValue',values);email.value='';name.value=''}catch(reason){error.value=reason instanceof Error?reason.message:'Check the attendee details.'}}
function remove(index:number){if(!props.disabled)emit('update:modelValue',props.modelValue.filter((_,i)=>i!==index))}
</script>
<template><section class="event-attendees" aria-label="Event attendees"><header><strong>Attendees</strong><small v-if="organizer">Organizer: {{organizer}}</small></header><div v-for="(attendee,index) in modelValue" :key="attendee.email" class="event-attendee-row"><span><strong>{{attendee.name||attendee.email}}</strong><small v-if="attendee.name">{{attendee.email}}</small></span><button type="button" class="icon-button" :disabled="disabled" :aria-label="`Remove attendee ${attendee.name||attendee.email}`" @click="remove(index)"><X :size="16"/></button></div><div v-if="!disabled" class="attendee-inputs"><label>Email<input v-model="email" type="email" maxlength="254" autocomplete="off" @keydown.enter.prevent="add"/></label><label>Name <small>optional</small><input v-model="name" maxlength="200" autocomplete="off" @keydown.enter.prevent="add"/></label><button type="button" class="button quiet" :disabled="!email.trim()||modelValue.length>=100" @click="add"><Plus :size="15"/>Add</button></div><p v-if="email||name" class="field-hint">Add this attendee or clear these fields before saving.</p><p v-if="!modelValue.length" class="field-hint">No attendees</p><p v-if="reason" class="field-hint">{{reason}}</p><p v-else-if="!disabled" class="field-hint">Nextcloud sends invitations when the event is saved. Delivery is handled by your server.</p><p v-if="error" class="inline-error" role="alert">{{error}}</p></section></template>
<style scoped>.event-attendees{margin:16px 0}.event-attendees header{display:flex;gap:8px;justify-content:space-between;flex-wrap:wrap;font-size:13px}.event-attendees small{display:block;color:var(--muted);font-weight:400}.event-attendee-row{display:flex;gap:8px;align-items:center;justify-content:space-between;padding:8px 0;border-bottom:1px solid var(--border);font-size:13px;overflow-wrap:anywhere}.attendee-inputs{display:grid;grid-template-columns:minmax(100px,1.3fr) minmax(80px,1fr) auto;align-items:end;gap:7px;margin:12px 0}.attendee-inputs label{font-size:12px}.attendee-inputs small{display:inline}.attendee-inputs input{margin-top:5px}@media(max-width:500px){.attendee-inputs{grid-template-columns:1fr auto}.attendee-inputs label:first-child{grid-column:1/-1}}</style>
